
public class Q9 {

    public static void main(String[] args) {
        // TODO Auto-generated method stub
        int a = Integer.parseInt(args[0]);
        int c = a/1000;
        int b = a%10;
        int sum = c+b;
        System.out.println("Sum of the first and last digit of " +a+ " is: "+sum );


    }

}
